function trywrite(path, val){
  try{
    const fd = require("fs").openSync(path, "w");
    require("fs").writeSync(fd, val);
    require("fs").closeSync(fd);
    console.log(path+": wrote "+JSON.stringify(val)+" OK");
  }catch(e){ console.log(path+": ERR "+e.code); }
}
